void test_a_redraw_is_wanted_when_fps_is_toggled_either_way(void) {
  overlay_drawn(&ov, 0);
  overlay_toggle_fps(&ov);
  TEST_ASSERT_TRUE(overlay_wants_redraw(&ov, 0));
  overlay_drawn(&ov, 0);
  overlay_toggle_fps(&ov);
  TEST_ASSERT_TRUE(overlay_wants_redraw(&ov, 0));
